import org.apache.spark.sql.SparkSession

object Main {
  def main(args: Array[String]): Unit = {
    val spark = SparkSession.builder.master("local[1]").getOrCreate()
    val zero = 0
    spark.sparkContext.parallelize(Seq(1, 2)).map(x => x / zero).collect()
    spark.stop()
  }
}

